<div class="section-heading studio-section-heading"><div><span class="website-kicker"><?= e(t('YOUR CONTROL ROOM')) ?></span><h2><?= e(t('Everything, in one place.')) ?></h2><p class="muted"><?= e(t('Content and operations for')) ?> <?= e($profile['name']) ?>.</p></div><span class="badge"><?= e(t('Local workspace')) ?></span></div>
<div class="studio-metrics"><?php foreach([['Content records',$summary['content'],'pages','Pages, projects, services & design'],['Open work',$summary['open'],'tasks','Active tasks and unresolved inquiries'],['Media files',$summary['media'],'media',number_format($summary['bytes']/1048576,1).' MB stored locally'],['Invoice balance',money($summary['due']),'invoices','Sent and overdue invoices']] as [$label,$value,$target,$detail]): ?><a class="card studio-metric" href="<?= $studioPath ?>?section=<?= $target ?>"><span><?= e($label) ?></span><strong><?= e($value) ?></strong><small><?= e($detail) ?></small></a><?php endforeach; ?></div>
<section class="card studio-quick"><div><h3><?= e(t('What are you working on?')) ?></h3><p class="muted"><?= e(t('One place for creating content and running the business.')) ?></p></div><div class="studio-quick-actions"><?php foreach(['pages'=>t('New page'),'projects'=>t('Add project'),'inquiries'=>t('Log inquiry'),'tasks'=>t('Create task'),'invoices'=>t('New invoice'),'media'=>t('Upload media')] as $key=>$label): ?><a class="btn secondary" href="<?= $studioPath ?>?section=<?= $key ?>#studio-editor">+ <?= e($label) ?></a><?php endforeach; ?></div></section>
<div class="two-col"><section class="card"><div class="section-heading"><h3><?= e(t('Workspace distribution')) ?></h3><span class="badge"><?= e(t('Real saved records')) ?></span></div><?php if($summary['content']+$summary['operations']>0): ?><?= chart('doughnut',['Content','Operations'],[['label'=>t('Workspace records'),'data'=>[$summary['content'],$summary['operations']],'backgroundColor'=>['#3688ff','#9f8bff']]],['cutout'=>'70%']) ?><?php else: ?><div class="studio-empty"><span class="studio-empty-icon"><?= icon('grid') ?></span><h3><?= e(t('Your workspace starts here.')) ?></h3><p class="muted"><?= e(t('Add your first content or operations record to see its distribution.')) ?></p><a href="<?= $studioPath ?>?section=pages"><?= e(t('Create a page')) ?> <?= icon('arrow-right') ?></a></div><?php endif; ?></section><section class="card"><div class="section-heading"><h3><?= e(t('Recent activity')) ?></h3><a href="<?= $studioPath ?>?section=activity"><?= e(t('View all')) ?></a></div><?php if(!$summary['activity']): ?><p class="studio-empty muted"><?= e(t('Saves and uploads will appear here.')) ?></p><?php else: foreach(array_slice($summary['activity'],0,5) as $entry): ?><article class="studio-activity"><span class="studio-activity-mark"><?= icon('check') ?></span><div><strong><?= e($entry['record_title']) ?></strong><p><?= e(ucfirst($entry['action'])) ?> · <?= e($definitions[$entry['section']]['label'] ?? t('Media library')) ?></p></div></article><?php endforeach; endif; ?></section></div>
<section class="card"><div class="section-heading"><h3><?= e(t('Recently edited')) ?></h3><a href="<?= $studioPath ?>?section=activity"><?= e(t('Activity log')) ?> <?= icon('arrow-right') ?></a></div><?php if(!$summary['recent']): ?><p class="muted"><?= e(t('No records yet. Add a page, project, customer or task to begin.')) ?></p><?php else: foreach($summary['recent'] as $record): ?><a class="studio-recent" href="<?= $studioPath ?>?section=<?= e($record['section']) ?>&amp;edit=<?= e($record['id']) ?>#studio-editor"><span><strong><?= e($record['title']) ?></strong><small><?= e($definitions[$record['section']]['label']) ?></small></span><span class="badge"><?= e($definitions[$record['section']]['statuses'][$record['status']]) ?></span><span class="studio-recent-time"><?= e($record['updated_at']) ?></span><?= icon('arrow-right') ?></a><?php endforeach; endif; ?></section>
